    /** The filled twin of [outline], for its selected state, or null where it has none. */
    fun selectedOf(outline: ImageVector): FilledIcon? = when (outline.name) {
        "Home" -> HomeSelected
        "Chats" -> ChatsSelected
        "Settings" -> SettingsSelected
        "Search" -> SearchSelected
        "StarOutline" -> StarOutlineSelected
        "Bookmark" -> BookmarkSelected
        "Folder" -> FolderSelected
        "Clock" -> ClockSelected
        "Play" -> PlaySelected
        "Person" -> PersonSelected
        "Archive" -> ArchiveSelected
        "Channel" -> ChannelSelected
        else -> null
    }

    /** One shape of a glyph: its SVG path data and whether it is stroked, filled or both. */
    private class Part(val d: String, val stroke: Boolean, val fill: Boolean, val evenOdd: Boolean, val alpha: Float, val width: Float)

    private fun s(d: String, alpha: Float = 1f, width: Float = 1.5f) = Part(d, stroke = true, fill = false, evenOdd = false, alpha = alpha, width = width)
    private fun f(d: String, evenOdd: Boolean = false, alpha: Float = 1f) = Part(d, stroke = false, fill = true, evenOdd = evenOdd, alpha = alpha, width = 1.5f)
    private fun sf(d: String, alpha: Float = 1f, width: Float = 1.5f) = Part(d, stroke = true, fill = true, evenOdd = false, alpha = alpha, width = width)

    private val Ink = SolidColor(Color.Black)

    private fun icon(name: String, vararg parts: Part, autoMirror: Boolean = false): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
            autoMirror = autoMirror,
        )
        for (part in parts) {
            builder.addPath(
                pathData = PathParser().parsePathString(part.d).toNodes(),
                pathFillType = if (part.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = if (part.fill) Ink else null,
                fillAlpha = part.alpha,
                stroke = if (part.stroke) Ink else null,
                strokeAlpha = part.alpha,
                strokeLineWidth = part.width,
                strokeLineCap = StrokeCap.Round,
                strokeLineJoin = StrokeJoin.Round,
                // The round join is not always honoured, and a sharp corner (the Archive lid's ends)
                // then grows a miter spike past the glyph; a limit of 1 bevels it instead.
                strokeLineMiter = 1f,
            )
        }
        return builder.build()
    }
}
